-- ========================================= -- TABELA: media_type -- =========================================
CREATE TABLE media_type (
mety_cd_id UUID PRIMARY KEY,
mety_tx_name VARCHAR(50) NOT NULL UNIQUE
);
-- ========================================= -- DEFAULT TYPES -- =========================================
INSERT INTO media_type (mety_cd_id, mety_tx_name) VALUES ('8a8f4c5c-0b9c-4b41-9c9e-2c6b9f7d4e0a', 'IMAGE'), ('b7a1d4c9-2f5e-4a3b-8c6d-1e9f0a2b3c4d', 'VIDEO'), ('5c9e2b7a-4f1d-4e8a-b6c3-7a0d9f2e1b5c', 'FILE');
-- ========================================= -- TABELA: post -- =========================================
CREATE TABLE post (
post_cd_id UUID PRIMARY KEY,
usac_tx_username TEXT NOT NULL,
post_tx_title VARCHAR(150) NOT NULL,
post_tx_description TEXT,
post_bt_thumb BYTEA NOT NULL,
post_nm_published BOOLEAN DEFAULT FALSE NOT NULL,
post_nm_fixed BOOLEAN DEFAULT FALSE NOT NULL,
post_dt_created_at TIMESTAMP NOT NULL,
post_dt_updated_at TIMESTAMP
);
-- ========================================= -- TABELA: media -- =========================================
CREATE TABLE media (
medi_cd_id UUID PRIMARY KEY,
medi_bt_content BYTEA NOT NULL,
mety_cd_id UUID NOT NULL REFERENCES media_type(mety_cd_id),
post_cd_id UUID NOT NULL REFERENCES post(post_cd_id)
);
-- ========================================= -- INDEXES -- =========================================
CREATE INDEX idx_post_author ON post(usac_tx_username);
CREATE INDEX idx_post_created ON post(post_dt_created_at DESC);
